begin; do $$ begin if to_regclass('public.students') is not null or exists (select 1 from auth.users) then raise exception 'STOP: this database is not empty. This SQL is only for a brand-new test project.'; end if; end; $$; create table academies ( id uuid primary key default gen_random_uuid() ); alter table academies enable row level security; create table students ( id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), academy_id uuid, name text not null, grade text, pin text, school_name text, student_phone text, parent_phone text, enrolled_at date, notes text, created_at timestamptz default now() ); alter table students enable row level security; create policy "select_own_students" on students for select using (auth.uid() = user_id); create policy "insert_own_students" on students for insert with check (auth.uid() = user_id); create policy "delete_own_students" on students for delete using (auth.uid() = user_id); create table question_sets ( id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), academy_id uuid, grade text, topic text, passage text, translation text, items jsonb, questions jsonb, sentences jsonb, essay_questions jsonb, summary_questions jsonb, reading_questions jsonb, created_at timestamptz default now() ); alter table question_sets enable row level security; create policy "본인 명의로만 추가 가능" on question_sets for insert with check (auth.uid() = user_id); create policy "본인 문제 세트만 삭제" on question_sets for delete using (auth.uid() = user_id); create policy "본인 문제 세트만 조회" on question_sets for select using (auth.uid() = user_id); create table questions ( id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), academy_id uuid, question_set_id uuid references question_sets(id), question_type text, question_text text, passage_blank_text text, choices jsonb, correct_answer text, explanation text, grade text, topic text, difficulty integer, tags text[] default '{}', weakness_tags text[] default '{}', status text, review_note text, last_used_at timestamptz, usage_count integer default 0, essay_meta jsonb, created_at timestamptz default now(), updated_at timestamptz default now() ); alter table questions enable row level security; create policy "questions_select_own" on questions for select using (auth.uid() = user_id); create policy "questions_insert_own" on questions for insert with check (auth.uid() = user_id); create policy "questions_update_own" on questions for update using (auth.uid() = user_id) with check (auth.uid() = user_id); create policy "questions_delete_own" on questions for delete using (auth.uid() = user_id); create table exams ( id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), academy_id uuid, title text not null, exam_date date, question_set_id uuid references question_sets(id), total_questions integer, max_score integer, created_at timestamptz default now() ); alter table exams enable row level security; create policy "exams_select_own" on exams for select using (auth.uid() = user_id); create policy "exams_insert_own" on exams for insert with check (auth.uid() = user_id); create policy "exams_update_own" on exams for update using (auth.uid() = user_id) with check (auth.uid() = user_id); create policy "exams_delete_own" on exams for delete using (auth.uid() = user_id); create table exam_results ( id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), student_id uuid not null references students(id) on delete cascade, exam_id uuid references exams(id), exam_title text, score numeric, max_score numeric, exam_date date, created_at timestamptz default now() ); alter table exam_results enable row level security; create policy "select_own_exam_results" on exam_results for select using (auth.uid() = user_id); create policy "insert_own_exam_results" on exam_results for insert with check (auth.uid() = user_id); create policy "delete_own_exam_results" on exam_results for delete using (auth.uid() = user_id); create or replace function public.get_student_report(p_student_id uuid, p_pin text) returns json language plpgsql security definer as $function$ declare v_student record; v_results json; begin select id, name, grade into v_student from students where id = p_student_id and pin = p_pin; if v_student.id is null then return json_build_object('found', false); end if; select json_agg( json_build_object( 'exam_title', exam_title, 'score', score, 'max_score', max_score, 'exam_date', exam_date ) order by exam_date asc ) into v_results from exam_results where student_id = v_student.id; return json_build_object( 'found', true, 'name', v_student.name, 'grade', v_student.grade, 'results', coalesce(v_results, '[]'::json) ); end; $function$; create table if not exists exam_sheets ( id uuid primary key default gen_random_uuid(), created_at timestamptz default now(), user_id uuid, title text, style_preset text, style_params jsonb, grade_level text, question_config jsonb, questions_data jsonb ); alter table exam_sheets add column if not exists user_id uuid, add column if not exists style_preset text, add column if not exists style_params jsonb, add column if not exists grade_level text, add column if not exists question_config jsonb, add column if not exists questions_data jsonb, add column if not exists title text; alter table exam_sheets enable row level security; drop policy if exists "Allow all for now" on exam_sheets; create policy "Allow all for now" on exam_sheets for all using (true) with check (true); CREATE TABLE IF NOT EXISTS exam_questions ( id UUID DEFAULT gen_random_uuid() PRIMARY KEY, exam_id UUID REFERENCES exams(id) ON DELETE CASCADE, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, question_data JSONB NOT NULL, sort_order INTEGER DEFAULT 0, points INTEGER DEFAULT 5, created_at TIMESTAMPTZ DEFAULT NOW() ); ALTER TABLE exam_questions ENABLE ROW LEVEL SECURITY; CREATE POLICY "exam_questions_own" ON exam_questions FOR ALL USING (auth.uid() = user_id); CREATE TABLE IF NOT EXISTS attendance ( id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, student_id UUID REFERENCES students(id) ON DELETE CASCADE, date DATE NOT NULL, status TEXT NOT NULL DEFAULT 'present' CHECK (status IN ('present', 'absent', 'late', 'excused')), note TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(user_id, student_id, date) ); ALTER TABLE attendance ENABLE ROW LEVEL SECURITY; CREATE POLICY "attendance_own" ON attendance FOR ALL USING (auth.uid() = user_id); CREATE TABLE IF NOT EXISTS schedule_events ( id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, title TEXT NOT NULL, event_date DATE NOT NULL, start_time TEXT, end_time TEXT, event_type TEXT DEFAULT 'class' CHECK (event_type IN ('class', 'exam', 'holiday', 'other')), note TEXT, created_at TIMESTAMPTZ DEFAULT NOW() ); ALTER TABLE schedule_events ENABLE ROW LEVEL SECURITY; CREATE POLICY "schedule_events_own" ON schedule_events FOR ALL USING (auth.uid() = user_id); CREATE TABLE IF NOT EXISTS tuition_records ( id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, student_id UUID REFERENCES students(id) ON DELETE CASCADE, month_name TEXT NOT NULL, amount INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'unpaid' CHECK (status IN ('paid', 'unpaid', 'partial')), paid_at DATE, note TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(user_id, student_id, month_name) ); ALTER TABLE tuition_records ENABLE ROW LEVEL SECURITY; CREATE POLICY "tuition_records_own" ON tuition_records FOR ALL USING (auth.uid() = user_id); CREATE TABLE IF NOT EXISTS parent_notifications ( id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, student_id UUID REFERENCES students(id) ON DELETE CASCADE, title TEXT NOT NULL, message TEXT NOT NULL, notification_type TEXT DEFAULT 'general', created_at TIMESTAMPTZ DEFAULT NOW() ); ALTER TABLE parent_notifications ENABLE ROW LEVEL SECURITY; CREATE POLICY "parent_notifications_own" ON parent_notifications FOR ALL USING (auth.uid() = user_id); SELECT 'Migration complete! 5 tables created.' AS result; CREATE TABLE IF NOT EXISTS reports ( id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, student_id UUID REFERENCES students(id) ON DELETE SET NULL, exam_id UUID REFERENCES exams(id) ON DELETE SET NULL, student_name TEXT NOT NULL, student_grade TEXT, exam_title TEXT, exam_date DATE, score INTEGER, max_score INTEGER DEFAULT 100, strengths TEXT, comment TEXT, next_steps TEXT, type_scores JSONB DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT NOW() ); ALTER TABLE reports ENABLE ROW LEVEL SECURITY; CREATE POLICY "reports_own" ON reports FOR ALL USING (auth.uid() = user_id); CREATE TABLE IF NOT EXISTS homework ( id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, student_id UUID REFERENCES students(id) ON DELETE CASCADE, title TEXT NOT NULL, due_date DATE, status TEXT NOT NULL DEFAULT 'assigned' CHECK (status IN ('assigned', 'done')), note TEXT, created_at TIMESTAMPTZ DEFAULT NOW() ); ALTER TABLE homework ENABLE ROW LEVEL SECURITY; CREATE POLICY "homework_own" ON homework FOR ALL USING (auth.uid() = user_id); CREATE TABLE IF NOT EXISTS passages ( id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, title TEXT NOT NULL, level TEXT, topic TEXT, body TEXT NOT NULL, tagged_body TEXT NOT NULL, tags JSONB DEFAULT '{}', questions JSONB DEFAULT '[]', essays JSONB DEFAULT '[]', created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW() ); ALTER TABLE passages ENABLE ROW LEVEL SECURITY; CREATE POLICY "passages_own" ON passages FOR ALL USING (auth.uid() = user_id); CREATE TABLE IF NOT EXISTS wrong_answer_records ( id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) NOT NULL, exam_id UUID REFERENCES exams(id) ON DELETE CASCADE, student_id UUID REFERENCES students(id) ON DELETE CASCADE, wrong_question_ids TEXT[] DEFAULT '{}', scored_at DATE, notes TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() ); ALTER TABLE wrong_answer_records ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users manage own wrong_answer_records" ON wrong_answer_records FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id); CREATE OR REPLACE FUNCTION update_wrong_answers_updated_at() RETURNS TRIGGER AS $$ BEGIN NEW.updated_at = NOW(); RETURN NEW; END; $$ LANGUAGE plpgsql; CREATE TRIGGER trg_wrong_answers_updated_at BEFORE UPDATE ON wrong_answer_records FOR EACH ROW EXECUTE FUNCTION update_wrong_answers_updated_at(); create table if not exists academy_settings ( user_id uuid references auth.users(id) on delete cascade primary key, academy_name text, logo_url text, signature_url text, updated_at timestamptz default now() ); alter table academy_settings enable row level security; drop policy if exists "academy_settings_own" on academy_settings; create policy "academy_settings_own" on academy_settings for all using (auth.uid() = user_id) with check (auth.uid() = user_id); insert into storage.buckets (id, name, public) values ('brand', 'brand', true) on conflict (id) do nothing; drop policy if exists "brand_read_public" on storage.objects; create policy "brand_read_public" on storage.objects for select using (bucket_id = 'brand'); drop policy if exists "brand_write_own_folder" on storage.objects; create policy "brand_write_own_folder" on storage.objects for insert with check (bucket_id = 'brand' and (storage.foldername(name))[1] = auth.uid()::text); drop policy if exists "brand_update_own_folder" on storage.objects; create policy "brand_update_own_folder" on storage.objects for update using (bucket_id = 'brand' and (storage.foldername(name))[1] = auth.uid()::text); create table if not exists api_usage_logs ( id bigint generated always as identity primary key, user_id uuid references auth.users(id) on delete set null, route text not null, model text not null, input_tokens integer not null default 0, output_tokens integer not null default 0, created_at timestamptz default now() ); alter table api_usage_logs enable row level security; drop policy if exists "api_usage_logs_own_select" on api_usage_logs; create policy "api_usage_logs_own_select" on api_usage_logs for select using (auth.uid() = user_id); drop policy if exists "api_usage_logs_own_insert" on api_usage_logs; create policy "api_usage_logs_own_insert" on api_usage_logs for insert with check (auth.uid() = user_id); update exam_sheets set user_id = 'ac06fc89-db8e-41a3-be98-3e43178b2c0d' where user_id is null; alter table exam_sheets alter column user_id set not null; drop policy if exists "Allow all for now" on exam_sheets; create policy "exam_sheets_own" on exam_sheets for all using (auth.uid() = user_id) with check (auth.uid() = user_id); create table if not exists passage_groups ( id uuid default gen_random_uuid() primary key, user_id uuid references auth.users(id) on delete cascade, title text not null, level text, topic text, source_body text not null, status text not null default 'pending' check (status in ('pending', 'generating', 'completed', 'partial', 'failed')), created_at timestamptz default now(), updated_at timestamptz default now() ); alter table passage_groups enable row level security; drop policy if exists "passage_groups_own" on passage_groups; create policy "passage_groups_own" on passage_groups for all using (auth.uid() = user_id) with check (auth.uid() = user_id); alter table passages add column if not exists group_id uuid references passage_groups(id) on delete cascade, add column if not exists variant_level text; alter table passages drop constraint if exists passages_variant_level_check; alter table passages add constraint passages_variant_level_check check (variant_level is null or variant_level in ('school', 'academy', 'advanced', 'prestudy')); alter table passages drop constraint if exists passages_group_variant_pair_check; alter table passages add constraint passages_group_variant_pair_check check ((group_id is null) = (variant_level is null)); create unique index if not exists passages_group_variant_unique on passages (group_id, variant_level) where group_id is not null; create index if not exists passages_group_id_idx on passages (group_id); CREATE TABLE IF NOT EXISTS attendance ( id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, student_id UUID REFERENCES students(id) ON DELETE CASCADE, date DATE NOT NULL, status TEXT NOT NULL DEFAULT 'present' CHECK (status IN ('present', 'absent', 'late', 'excused')), note TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(user_id, student_id, date) ); ALTER TABLE attendance ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "attendance_own" ON attendance; CREATE POLICY "attendance_own" ON attendance FOR ALL USING (auth.uid() = user_id); CREATE TABLE IF NOT EXISTS schedule_events ( id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, title TEXT NOT NULL, event_date DATE NOT NULL, start_time TEXT, end_time TEXT, event_type TEXT DEFAULT 'class' CHECK (event_type IN ('class', 'exam', 'holiday', 'other')), note TEXT, created_at TIMESTAMPTZ DEFAULT NOW() ); ALTER TABLE schedule_events ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "schedule_events_own" ON schedule_events; CREATE POLICY "schedule_events_own" ON schedule_events FOR ALL USING (auth.uid() = user_id); CREATE TABLE IF NOT EXISTS tuition_records ( id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, student_id UUID REFERENCES students(id) ON DELETE CASCADE, month_name TEXT NOT NULL, amount INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'unpaid' CHECK (status IN ('paid', 'unpaid', 'partial')), paid_at DATE, note TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(user_id, student_id, month_name) ); ALTER TABLE tuition_records ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "tuition_records_own" ON tuition_records; CREATE POLICY "tuition_records_own" ON tuition_records FOR ALL USING (auth.uid() = user_id); CREATE TABLE IF NOT EXISTS parent_notifications ( id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, student_id UUID REFERENCES students(id) ON DELETE CASCADE, title TEXT NOT NULL, message TEXT NOT NULL, notification_type TEXT DEFAULT 'general', created_at TIMESTAMPTZ DEFAULT NOW() ); ALTER TABLE parent_notifications ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "parent_notifications_own" ON parent_notifications; CREATE POLICY "parent_notifications_own" ON parent_notifications FOR ALL USING (auth.uid() = user_id); ALTER TABLE tuition_records ADD COLUMN IF NOT EXISTS paid_amount INTEGER; alter table passage_groups add column if not exists archived boolean not null default false, add column if not exists archived_at timestamptz; alter table passages add column if not exists archived boolean not null default false, add column if not exists archived_at timestamptz; alter table passages drop constraint if exists passages_group_archived_check; alter table passages add constraint passages_group_archived_check check (group_id is null or archived = false); alter table passage_groups drop constraint if exists passage_groups_archived_pair_check; alter table passage_groups add constraint passage_groups_archived_pair_check check ((archived = false and archived_at is null) or (archived = true and archived_at is not null)); alter table passages drop constraint if exists passages_archived_pair_check; alter table passages add constraint passages_archived_pair_check check ((archived = false and archived_at is null) or (archived = true and archived_at is not null)); create index if not exists passage_groups_archived_idx on passage_groups (archived); create index if not exists passages_archived_idx on passages (archived); create table if not exists vocabulary_entries ( id uuid default gen_random_uuid() primary key, user_id uuid not null references auth.users(id) on delete cascade, expression text not null check (btrim(expression) <> ''), expression_key text generated always as ( lower(btrim(regexp_replace( translate(expression, E'\u2018\u2019\u201C\u201D\u2010\u2011\u2013\u2014\u2212\u00A0\u3000', E'\'\'""----- '), '[ \t\n\r\f\v]+', ' ', 'g'))) ) stored, lemma text, entry_type text not null default 'word' check (entry_type in ('word', 'phrasal_verb', 'collocation', 'idiom', 'phrase')), pos text check (pos is null or pos in ( 'noun', 'pronoun', 'verb', 'auxiliary', 'adjective', 'adverb', 'preposition', 'conjunction', 'determiner', 'interjection', 'numeral' )), meaning_ko text not null check (btrim(meaning_ko) <> ''), meaning_key text generated always as ( btrim(regexp_replace( translate(meaning_ko, E'\u00A0\u3000', ' '), '[ \t\n\r\f\v]+', ' ', 'g')) ) stored, accepted_meanings text[] not null default '{}', sense_note text, example_sentence text, base_difficulty smallint check (base_difficulty between 1 and 100), ko_en_difficulty smallint check (ko_en_difficulty between 1 and 100), ko_en_allowed boolean not null default false, status text not null default 'pending' check (status in ('pending', 'approved', 'rejected', 'archived')), reject_reason text check (reject_reason is null or reject_reason in ( 'level_mismatch', 'meaning_wrong', 'too_easy', 'too_hard', 'low_value', 'duplicate', 'extraction_error', 'other' )), reject_note text, approval_origin text check (approval_origin is null or approval_origin in ('individual', 'batch')), teacher_reviewed_at timestamptz, archived_at timestamptz, deleted_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now() ); alter table v