es_lemma_idx on vocabulary_entries (user_id, lemma) where lemma is not null; alter table vocabulary_entries enable row level security; drop policy if exists "vocabulary_entries_own" on vocabulary_entries; create policy "vocabulary_entries_own" on vocabulary_entries for all using (auth.uid() = user_id) with check (auth.uid() = user_id); create or replace function update_vocabulary_entries_updated_at() returns trigger as $$ begin new.updated_at = now(); return new; end; $$ language plpgsql; drop trigger if exists trg_vocabulary_entries_updated_at on vocabulary_entries; create trigger trg_vocabulary_entries_updated_at before update on vocabulary_entries for each row execute function update_vocabulary_entries_updated_at(); create table if not exists vocabulary_sources ( id uuid default gen_random_uuid() primary key, user_id uuid not null references auth.users(id) on delete cascade, entry_id uuid not null references vocabulary_entries(id) on delete cascade, source_type text not null check (source_type in ('official', 'external_passage', 'question_bank', 'teacher', 'manual_test')), source_ref text not null check (btrim(source_ref) <> ''), surface_form text, source_sentence text, context_meaning text, suggested_difficulty smallint check (suggested_difficulty between 1 and 100), rationale text, created_by text not null check (created_by in ('claude', 'teacher', 'import')), official_source_name text, official_source_version text, official_grade text, created_at timestamptz default now() ); alter table vocabulary_sources drop constraint if exists vocabulary_sources_official_fields_check; alter table vocabulary_sources add constraint vocabulary_sources_official_fields_check check ( (source_type = 'official' and official_source_name is not null and official_source_version is not null) or (source_type <> 'official' and official_source_name is null and official_source_version is null and official_grade is null) ); create unique index if not exists vocabulary_sources_entry_source_